  'terms.summary.title': 'باختصار',
  'terms.summary.kind': 'كن لطيفًا. لا تنمّر ولا كراهية ولا تهديد ولا محتوى للبالغين.',
  'terms.summary.own': 'انشر ما صنعته بنفسك. كلمات أو صورة لشخص آخر؟ فقط إن كان مسموحًا لك — واذكر صاحبها.',
