  'meta.home.title': 'Hevalo — تعلّم الكردية والكرمانجية مع أصدقائك',
  'meta.about.title': 'عن Hevalo — الكردية، نتعلّمها معًا',
  'meta.about.description': 'لماذا وُجد Hevalo، وماذا يقدّم اليوم، وما الذي سيأتي: مكان لتعلّم الكردية، والكرمانجية أولًا، عبر الألعاب والأصدقاء والمجتمع.',
  'meta.privacy.title': 'الخصوصية · Hevalo',
  'meta.privacy.description': 'ما الذي يحتفظ به Hevalo، ولماذا، وما الذي تتحكم فيه أنت. لا إعلانات، ولا تتبّع عبر التطبيقات والمواقع الأخرى، ولا تُباع بياناتك أبدًا.',
